/* ------------------------------------------------------------------ glossary */
const GLOSSARY = [
  ["5GC", "5G Core network: the service-based core made of AMF, SMF, UPF, AUSF, UDM, PCF, NRF, NSSF, NEF and others."],
  ["5QI", "5G QoS Identifier. Points to standard QoS characteristics: resource type (GBR / non-GBR / delay-critical), priority, delay budget, error rate. Examples: 1 voice, 2 conversational video, 9 best-effort internet, 82+ delay-critical (URLLC)."],
  ["5G-AKA", "5G Authentication and Key Agreement. The USIM and the home network prove to each other that both know K, without sending K."],
  ["5G-GUTI", "5G Globally Unique Temporary Identifier, made of the GUAMI and the 5G-TMSI. Used instead of the SUPI to protect privacy."],
  ["AMBR", "Aggregate Maximum Bit Rate: a cap on the total non-GBR traffic of a session (Session-AMBR) or a UE (UE-AMBR)."],
  ["ARP", "Allocation and Retention Priority. Decides who is admitted or pre-empted when resources are short."],
  ["BWP", "Bandwidth Part: a subset of the carrier a UE uses, so it can save power or use a different numerology."],
  ["C-RNTI", "Cell Radio Network Temporary Identifier: the UE's 16-bit address in a cell while RRC_CONNECTED."],
  ["CM state", "Connection Management: CM-IDLE (no NAS signalling connection) or CM-CONNECTED."],
  ["CQI", "Channel Quality Indicator: the UE's recommended modulation and code rate for ≤10% BLER (TS 38.214)."],
  ["CSI-RS", "Channel State Information Reference Signal, measured by the UE to report CQI/PMI/RI and to track beams."],
  ["CU / DU / RU", "gNB split: Central Unit (RRC, PDCP, SDAP), Distributed Unit (RLC, MAC, high PHY), Radio Unit (low PHY, RF)."],
  ["CUPS", "Control and User Plane Separation: the SMF decides and the UPF forwards, joined by PFCP over N4."],
  ["DNN", "Data Network Name, the 5G equivalent of the APN, e.g. \"internet\" or \"ims\"."],
  ["DRB", "Data Radio Bearer: carries user data over the air. One or more QoS flows are mapped onto it by SDAP."],
  ["DRX", "Discontinuous Reception: the UE sleeps and wakes periodically to save battery."],
  ["FAR", "Forwarding Action Rule (PFCP): forward, buffer, drop, or notify, plus the encapsulation to apply."],
  ["GBR", "Guaranteed Bit Rate: a QoS flow whose rate is reserved by admission control."],
  ["GTP-U", "GPRS Tunnelling Protocol, user plane: tunnels user packets between gNB and UPF, identified by TEIDs."],
  ["GUAMI", "Globally Unique AMF Identifier: PLMN + AMF Region + AMF Set + AMF Pointer."],
  ["HARQ", "Hybrid ARQ: fast retransmission with soft combining at MAC/PHY."],
  ["KgNB / KAMF", "Keys in the 5G key hierarchy: KAUSF → KSEAF → KAMF → KgNB → radio keys. K stays in the USIM and the UDM."],
  ["MCS", "Modulation and Coding Scheme index chosen by the scheduler for each transmission."],
  ["MIB / SIB", "Master and System Information Blocks broadcast by every cell. They tell UEs how to access it."],
  ["NAS", "Non-Access Stratum: signalling between UE and core (5GMM with the AMF, 5GSM with the SMF)."],
  ["NGAP", "NG Application Protocol on N2 between gNB and AMF."],
  ["Numerology μ", "Subcarrier spacing 15·2^μ kHz. The slot is 1 ms / 2^μ. μ = 1 (30 kHz) is typical for 3.5 GHz."],
  ["NR-ARFCN", "Absolute radio frequency channel number for NR, used to state carrier frequencies."],
  ["NSSAI / S-NSSAI", "Network slice identifiers. An S-NSSAI = SST (1 eMBB, 2 URLLC, 3 MIoT, 4 V2X) + optional SD (differentiator)."],
  ["PCI", "Physical Cell Identity (0–1007), from PSS and SSS."],
  ["PDR", "Packet Detection Rule (PFCP): matches packets by TEID, UE IP, SDF filter, etc."],
  ["PDU session", "A connection between the UE and a data network with an IP address, one or more QoS flows, and an anchor UPF."],
  ["PFCP", "Packet Forwarding Control Protocol on N4 (TS 29.244)."],
  ["PLMN", "Public Land Mobile Network: an operator network, identified by MCC + MNC."],
  ["PRACH", "Physical Random Access Channel: carries the Msg1 preamble."],
  ["PRB", "Physical Resource Block: 12 subcarriers in frequency, the unit the scheduler hands out."],
  ["QER", "QoS Enforcement Rule (PFCP): gating, MBR/GBR policing, QFI marking."],
  ["QFI", "QoS Flow Identifier: tags packets in GTP-U and SDAP so every node knows the flow's QoS."],
  ["QoS flow", "The finest QoS granularity in 5G. Packets with the same QFI get the same treatment."],
  ["RACH", "Random Access procedure (Msg1–Msg4, or 2-step MsgA/MsgB)."],
  ["RM state", "Registration Management: RM-DEREGISTERED or RM-REGISTERED."],
  ["RRC", "Radio Resource Control between UE and gNB: connection, security, bearers, measurements, handover."],
  ["RRC states", "RRC_IDLE (no connection), RRC_INACTIVE (context kept, fast resume), RRC_CONNECTED."],
  ["RSRP", "Reference Signal Received Power, the main coverage metric. Your twin maps it."],
  ["SBA / SBI", "Service-Based Architecture / Interface: core NFs expose REST APIs over HTTP/2."],
  ["SDAP", "Service Data Adaptation Protocol: maps QoS flows to DRBs on the radio."],
  ["SINR", "Signal to Interference plus Noise Ratio. It drives CQI, MCS and throughput."],
  ["SSB", "Synchronisation Signal Block (PSS + SSS + PBCH), sent as a sweep of beams."],
  ["SSC mode", "Session and Service Continuity: 1 keeps the IP anchor, 2 breaks before make, 3 makes before break."],
  ["SUPI / SUCI", "Subscription Permanent Identifier (like the IMSI) and its concealed form, encrypted with the home network public key."],
  ["TAC / TAI", "Tracking Area Code / Identity. The AMF tracks idle UEs per list of tracking areas."],
  ["TEID", "Tunnel Endpoint Identifier: the 32-bit GTP-U tunnel address, chosen by the receiver."],
  ["Timing Advance", "How much earlier the UE transmits so its uplink arrives aligned at the gNB."],
  ["URSP", "UE Route Selection Policy: rules from the PCF that tell the UE which slice/DNN each app uses."],
];
